CREATE VIEW mart_backlog_analysis AS SELECT dg.GameKey, dg.GameID, dg.GameTitle, dps.PlayStatusName, fpa.PlayActivityCount, fpa.InProgressCount, fpa.CompletedCount, fpa.UnplayedCount, dd_completion.FullDate AS CompletionDate, dd_last.FullDate AS LastPlayedDate, fuga.DifficultyScore, fuga.CompletionHours, fuga.PersonalRating, fuga.CuratedUserScore FROM FactPlayActivity AS fpa INNER JOIN DimGame AS dg ON ((dg.GameKey = fpa.GameKey)) INNER JOIN DimPlayStatus AS dps ON ((dps.PlayStatusKey = fpa.PlayStatusKey)) LEFT JOIN DimDate AS dd_completion ON ((dd_completion.DateKey = fpa.CompletionDateKey)) LEFT JOIN DimDate AS dd_last ON ((dd_last.DateKey = fpa.LastPlayedDateKey)) LEFT JOIN FactUserGameAssessment AS fuga ON ((fuga.GameKey = fpa.GameKey));
